inbox_dir="${1:?missing INBOX_DIR}"
out_file="${2:?missing OUT_FILE}"

python3 - "$inbox_dir" "$out_file" <<'PY'
import sys
import os
import json
import re
from collections import Counter
from email.utils import getaddresses

inbox_dir = sys.argv[1]
out_file = sys.argv[2]

counts = Counter()

try:
    entries = os.listdir(inbox_dir)
except FileNotFoundError:
    entries = []

basenames = []
for name in entries:
    if not name.endswith(".json"):
        continue
    full = os.path.join(inbox_dir, name)
    try:
        if not os.path.isfile(full):
            continue
    except Exception:
        continue
    basenames.append(name)

basenames.sort()

def record(addr):
    if not isinstance(addr, str):
        return False
    addr = addr.strip()
    if not addr or "@" not in addr:
        return False
    _local, _, domain = addr.rpartition("@")
    domain = domain.strip().lower()
    if not domain:
        return False
    if any(c in domain for c in (" ", "\t", "\r", "\n", ",", ";", "<", ">")):
        return False
    counts[domain] += 1
    return True

def add_domains_from_field(value):
    if value is None:
        return
    if isinstance(value, (list, tuple)):
        for v in value:
            add_domains_from_field(v)
        return
    if not isinstance(value, str):
        return
    if value.strip() == "":
        return
    try:
        pairs = getaddresses([value])
    except Exception:
        pairs = []
    found = False
    for _name, addr in pairs:
        if record(addr):
            found = True
    if found or "@" not in value:
        return
    # Fallback: header used ';' as separator (not RFC address-list commas)
    # or other odd-but-recoverable formatting. Only used when the
    # standards-compliant parse found nothing at all.
    try:
        pairs = getaddresses([value.replace(";", ",")])
    except Exception:
        pairs = []
    for _name, addr in pairs:
        if record(addr):
            found = True
    if found:
        return
    for tok in re.findall(r"[^\s,;<>]+@[^\s,;<>]+", value):
        record(tok)

for base in basenames:
    full = os.path.join(inbox_dir, base)
    try:
        with open(full, "r", encoding="utf-8") as f:
            data = json.load(f)
    except Exception:
        print(f"skip: {base}", file=sys.stderr)
        continue
    if isinstance(data, dict):
        to_val = data.get("to", None)
        cc_val = data.get("cc", None)
    else:
        to_val = None
        cc_val = None
    add_domains_from_field(to_val)
    add_domains_from_field(cc_val)

sorted_items = sorted(counts.items(), key=lambda kv: (-kv[1], kv[0]))

parent = os.path.dirname(os.path.abspath(out_file))
try:
    if parent and not os.path.exists(parent):
        os.makedirs(parent, exist_ok=True)
except Exception:
    pass

with open(out_file, "w", encoding="utf-8", newline="\n") as out:
    for domain, c in sorted_items:
        out.write(f"{c} {domain}\n")
PY
exit 0
